	regionKind = "zone",
	kind = "region",
	sections = {
		{
			title = "Summary",
			text = [=[Deadwind Pass is a barren cleft in the mountains between {link:duskwood}Duskwood{/link} and the {link:swamp-of-sorrows}Swamp of Sorrows{/link}. A cold wind moans through it without rest, and it has given the pass its name. Nothing grows well here. The trees stand grey and leafless, the grass is thin and colourless, and the sky above seems always the colour of ash. In the south of the pass, in a deep hollow of broken ground, rises the tower of {link:karazhan}Karazhan{/link}. It was the home of {link:medivh}Medivh{/link}, the last Guardian, and the place where he died. Travellers who must cross Deadwind keep to the road, speak little and do not look too long toward the tower.]=],
		},
		{
			title = "Origins",
			text = [=[No chronicle records who first named the pass, or whether it was ever green. What is certain is that it became known to the wider world through the tower at its heart. {link:medivh}Medivh{/link} made his home in {link:karazhan}Karazhan{/link} in the years before the {link:first-war}First War{/link}, and from there he worked the long designs that brought the orcs of {red:draenor}Draenor{/red} into {link:azeroth}Azeroth{/link}. The pass lay on the south-eastern edge of the old kingdom of {link:kingdom-of-stormwind}Azeroth{/link}, and few of the kingdom's folk had cause to go there. The Guardian was a friend of the king, and his tower was left in peace.]=],
		},
		{
			title = "The Present Day",
			text = [=[{link:medivh}Medivh{/link} is long dead, and his tower stands dark and shut. The pass belongs to no kingdom now. {link:kingdom-of-stormwind}Stormwind{/link} sends no patrols so far east, and the {link:horde}Horde{/link} holds no post here either. Restless spirits drift among the ruins at the foot of {link:karazhan}Karazhan{/link}, and pale, unliving things tend the graves of {link:morgan-s-plot}Morgan's Plot{/link} behind it. {link:ogres}Ogres{/link} have made their mounds along the southern road, in a narrow valley called the Vice. Great carrion birds wheel over the ravines. On the road itself, merchants and soldiers bound for {link:swamp-of-sorrows}the Swamp of Sorrows{/link} and the {link:blasted-lands}Blasted Lands{/link} hurry through by daylight. In {link:duskwood}Duskwood{/link}, the folk of {link:darkshire}Darkshire{/link} say that the {link:dark-riders}dark riders{/link} who slaughtered the Yorgen family came down out of this pass, and that no one knows where they go when they return.]=],
		},
		{
			title = "Inhabitants",
			text = [=[• {b}The restless dead.{/b} Shades, wailing spectres and damned souls haunt the ruined houses before {link:karazhan}Karazhan{/link}. Whose spirits they are, no living witness can say.
• {b}The unliving of {link:morgan-s-plot}Morgan's Plot{/link}.{/b} Pale caretakers and residents keep the chapel and graveyard behind the tower.
• {b}The Deadwind ogres.{/b} The {link:deadwind-ogres}ogres of Deadwind{/link} hold the mounds of the Vice and the {link:grosh-gok-compound}Grosh'gok Compound{/link}, with warlocks and {link:ogres}ogre{/link} mages among them.
• {b}Carrion birds.{/b} Vultures called sky shadows circle the northern ravines and the open ground of the pass.
• {b}The {link:dark-riders}dark riders{/link}.{/b} They are not seen here by day. Yet the survivors of {link:duskwood}Duskwood{/link} name Deadwind as the place from which they ride.]=],
		},
		{
			title = "History",
			text = [=[• {b}The Guardian's Tower.{/b} {link:medivh}Medivh{/link} took up his dwelling in {link:karazhan}Karazhan{/link} after he woke from the long sleep of his youth. There he studied, gathered a great library and received few guests.
• {b}The Opening of the Portal.{/b} From the tower, Medivh reached across the void to Draenor and to the warlock {link:gul-dan}Gul'dan{/link}. Together they opened the {link:dark-portal}Dark Portal{/link} in the Black Morass, far to the south.
• {b}The Apprentice and the Envoy.{/b} The {link:kirin-tor}Kirin Tor{/link} of {link:dalaran}Dalaran{/link} sent the young mage {link:khadgar}Khadgar{/link} to serve as Medivh's apprentice. The half-{link:orcs}orc{/link} {link:garona}Garona{/link} came to the tower as an envoy of the {link:horde}Horde{/link}. Between them they learned the truth of the Guardian's treachery.
• {b}The Death of the Guardian.{/b} Sir {link:anduin-lothar}Anduin Lothar{/link} and Khadgar climbed Karazhan and faced Medivh. There the Guardian was slain. Gul'dan, who had been reaching into Medivh's mind at that moment, fell into a long stupor.
• {b}The Silence.{/b} Since that day the tower has been dark. The {link:first-war}First War{/link} and the {link:second-war}Second War{/link} passed it by, and the pass around it has become a place that the living leave alone.]=],
		},
		{
			title = "Lore of the Pass",
			text = [=[• The road that runs from {link:duskwood}Duskwood{/link} toward {link:swamp-of-sorrows}the Swamp of Sorrows{/link} is the only safe way through. Old warnings stand beside it, and one of them says simply: "Turn Back!"
• Beside the crossroads stands a dead tree, and the hanged still swing from its branches. No one in Duskwood claims to know who hanged them.
• The ogres of the Vice keep bonfires and great cauldrons burning in their camps. What they hope to find in so dead a land, no one has asked them.
• Behind the tower lies a small chapel and a graveyard. Whatever congregation once gathered there, its dead do not rest.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells why the land of the pass is so barren, nor whether it was so before {link:medivh}Medivh{/link} came. Nor does any account say who lived in the ruined houses beneath {link:karazhan}Karazhan{/link}, or what became of them. This entry records what travellers see and what the histories of the Guardian affirm.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:sven-yorgen}Sven{/link}'s Revenge, where the {link:dark-riders}dark riders{/link} of Deadwind are first named]=],
			unlock = {
				{ type = "quest", id = 95 },
			},
		},
	},
})

