	sections = {
		{
			title = "Summary",
			text = [=[Karazhan is the tower of {link:medivh}Medivh{/link}, the last Guardian. It rises from a deep hollow in the south of {link:deadwind-pass}Deadwind Pass{/link}, a tall spire of dark stone above a scatter of ruined houses. For years it was the seat of one of the mightiest mages the world has known. It is also the place from which the {link:first-war}First War{/link} was set in motion, and the place where its maker died. Its doors are closed now. No servant answers at its gate, and no light is lit for guests.]=],
		},
		{
			title = "The Guardian's House",
			text = [=[{link:medivh}Medivh{/link} came to Karazhan as a grown man, after the long sleep of his youth in {link:northshire-abbey}Northshire Abbey{/link}. He lived there with only a small household of servants, led by an aged castellan. The tower held a great library, rooms of strange instruments and an observatory open to the stars. Those who stayed within its walls found that it did not always keep to the present. {link:khadgar}Khadgar{/link}, in his time as apprentice, saw scenes rise and fade in its halls that belonged to other days, some long past and some that had not yet come. The magi of the {link:kirin-tor}Kirin Tor{/link} had long wished to learn the secrets of the tower. None of them was ever invited in, until the Guardian at last agreed to take an apprentice.]=],
		},
		{
			title = "The Treachery",
			text = [=[Within these walls {link:medivh}Medivh{/link} reached across the void to the dying world of {red:draenor}Draenor{/red}. He found the warlock {link:gul-dan}Gul'dan{/link} and the orcs who served him, and together they opened the {link:dark-portal}Dark Portal{/link}. For years the Guardian's friends in {link:stormwind-city}Stormwind{/link} knew nothing of it. The truth came out of the tower through two unlikely allies: {link:khadgar}Khadgar{/link}, the apprentice sent by {link:dalaran}Dalaran{/link}, and {link:garona}Garona{/link}, the half-{link:orcs}orc{/link} envoy of the {link:horde}Horde{/link}. What they learned in Karazhan they carried to King {link:llane-wrynn}Llane Wrynn{/link}.]=],
		},
		{
			title = "The Last Battle",
			text = [=[Sir {link:anduin-lothar}Anduin Lothar{/link} and {link:khadgar}Khadgar{/link} returned to Karazhan to end the war at its root, and {link:garona}Garona{/link} stood with them. They fought the Guardian in his own tower, and {link:medivh}Medivh{/link} was slain. In that same moment, {link:gul-dan}Gul'dan{/link} was searching the Guardian's mind for the secrets of the Tomb of {link:sargeras}Sargeras{/link}. When Medivh died, the warlock was cast into a stupor from which he did not wake for a long time. Khadgar came down from the tower aged far beyond his years. Karazhan was left empty behind him.]=],
		},
		{
			title = "In These Days",
			text = [=[The tower is sealed. The spirits that drift among the ruined houses at its feet are the only company it keeps. Yet {link:medivh}Medivh{/link}'s knowledge has not wholly vanished. The essays of {link:khadgar}Khadgar{/link}, the tower's last apprentice, are still copied and studied by the learned of {link:stormwind-city}Stormwind{/link}, and the watchers who guard the {link:dark-portal}Dark Portal{/link} from {link:nethergarde-keep}Nethergarde Keep{/link} seek them out.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle tells who raised Karazhan, when it was built, or why it stands in so desolate a place. What lies behind its sealed doors in these days, no living witness has written.]=],
		},
	},
	chapters = {
		{
			key = "the-apprentice-s-essays",
