			hint = [=[Recover a scholar's lost essay and bring it to the watchers who guard the Dark Portal.]=],
			unlock = {
				{ type = "quest", id = 1364 },
			},
			text = [=[A courier of the {link:stormwind-city}Stormwind{/link} academy set out for {link:nethergarde-keep}Nethergarde{/link} with a precious text: {link:khadgar}Khadgar{/link}'s essays on the convergence of worlds. He lost it in {link:swamp-of-sorrows}the Swamp of Sorrows{/link}, to creatures of the marsh. When at last it reached the keep, the watcher who had asked for it could hardly wait to begin. The man who had once studied at {link:medivh}Medivh{/link}'s side had come to understand, better than anyone living, how two worlds had been joined. Those who now keep watch over the Portal wished to understand it too.]=],
